import{_ as t,o as a,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Welcome","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/bienvenue.md","filePath":"src/en/guide/bienvenue.md"}'),o={name:"en/guide/bienvenue.md"};function i(s,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h1><p>Kura is the administrative and financial platform of NextBoxx, edPage group&#39;s training organisation. It accompanies a person from their application to their certificate, and tracks everything administrative along the way: file, agreement, payments, attendance, results.</p><h2 id="kura-and-seve" tabindex="-1">Kura and Sève <a class="header-anchor" href="#kura-and-seve" aria-label="Permalink to &quot;Kura and Sève&quot;">​</a></h2><p>Two tools share the journey:</p><table tabindex="0"><thead><tr><th></th><th>Kura</th><th>Sève</th></tr></thead><tbody><tr><td>Role</td><td>File, agreements, invoices, certificates</td><td>Courses, virtual classes, grades, messaging</td></tr><tr><td>You use it to</td><td>Apply, sign, pay, download your documents</td><td>Follow your training</td></tr><tr><td>Sign-in</td><td>NextBoxx account (e-mail and password)</td><td>The same NextBoxx account: Sève relies on Kura to identify you, with no second password</td></tr></tbody></table><p>Your Sève account is opened for you once the first instalment of the training is paid. Kura then passes on to Sève what concerns your access: opening, suspension in case of non-payment, switch to the Canopé state after the certificate. In the other direction, Sève sends back to Kura your attendance at virtual classes and your grades.</p><h2 id="one-account-several-roles" tabindex="-1">One account, several roles <a class="header-anchor" href="#one-account-several-roles" aria-label="Permalink to &quot;One account, several roles&quot;">​</a></h2><p>A person has a single NextBoxx account, identified by their e-mail address. The account accumulates roles over time: candidate, then learner, then Canopé, and perhaps trainer or event funder later. An account is never created twice.</p><p>What you see in the menu depends on your roles. It is arranged in six sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>Content</th></tr></thead><tbody><tr><td>Overview</td><td>Dashboard, Direction view, reporting</td></tr><tr><td>Training</td><td>Catalogue, cohorts, profitability, communication</td></tr><tr><td>Journeys</td><td>Candidatures, enrolments, company requests, My enrolment, My documents</td></tr><tr><td>Activities</td><td>Events, L&#39;Éclosion, technology partnerships</td></tr><tr><td>Finance</td><td>Billing, commissions, remunerations</td></tr><tr><td>Administration</td><td>Role requests, users, organization accounts, settings</td></tr></tbody></table><p>An entry missing from your menu is not open to you: ask for the matching role (see <a href="./premiers-pas.html#ask-for-a-role">Getting started</a>).</p><h2 id="how-to-read-this-guide" tabindex="-1">How to read this guide <a class="header-anchor" href="#how-to-read-this-guide" aria-label="Permalink to &quot;How to read this guide&quot;">​</a></h2><p>Each role has its own section, in the left-hand menu. Start with <a href="./premiers-pas.html">Getting started</a>, common to everyone, then go to your journey.</p><ul><li><strong>You are applying for a training, or already following yours</strong>: <a href="./apprenant/candidature.html">The learner&#39;s journey</a>.</li><li><strong>You represent a company</strong> (funding a learner, training your teams, recruiting): <a href="./entreprises/financeur.html">Companies and funders</a>.</li><li><strong>You teach, coach or handle applications</strong>: <a href="./equipe/formateur.html">The pedagogical team</a>.</li><li><strong>You coordinate the training</strong> (catalogue, cohorts, billing, certification): <a href="./coordinateur/catalogue.html">Pedagogical Coordinator</a>.</li><li><strong>You take part in an event, fund, incubate or build a partnership</strong>: <a href="./activites/evenements.html">Extended activities</a>.</li><li><strong>You steer or administer the platform</strong>: <a href="./direction/pilotage.html">Direction and reporting</a> and <a href="./administrateur/comptes-et-roles.html">Administrator</a>.</li></ul>',14)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
